// 09/10: previsão do tempo e ações com outros clientes Dyno (mensagem, lista, lembrete, agenda).
const TZ = 'America/Sao_Paulo';
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const a = j.a || {};
  const base = { numero: String(j.numero || ''), autor: String(j.autor || ''), teste: j.teste === true };
  if (!base.numero || !base.autor) continue;
  if (a.tipo === 'previsao_tempo') {
    let dia = DateTime.fromISO(String(a.data || '').slice(0, 10), { zone: TZ });
    if (!dia.isValid) dia = DateTime.now().setZone(TZ);
    const local = String(a.local || '').trim().slice(0, 80) || 'São Paulo';
    out.push({ json: { ...base, kind: 'tempo', local, busca: local.split(',')[0].trim(), dia: dia.toISODate() } });
  } else if (a.tipo === 'contato') {
    const p = {
      autor: base.autor, numero_conversa: base.numero, nome_remetente: String(j.nome_exibicao || ''),
      op: String(a.op || 'mensagem'), para: String(a.para || ''), numero_para: String(a.numero || a.numero_para || ''),
      texto: a.texto ? String(a.texto) : '', titulo: a.titulo ? String(a.titulo) : '', itens: Array.isArray(a.itens) ? a.itens.map(String) : [],
      quando: a.quando ? String(a.quando) : '', inicio: a.inicio ? String(a.inicio) : '', local: a.local ? String(a.local) : '', lembrar_min: a.lembrar_min || null
    };
    out.push({ json: { ...base, kind: 'contato', p } });
  }
}
return out;

const TZ = 'America/Sao_Paulo';
const NL = String.fromCharCode(10);
const ped = $('Rotear').item.json;
const geo = $('Escolher cidade').item.json || {};
const f = $json || {};
const nrm = x => String(x || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const rs = geo.results || [];
const cid = rs[0];
const COD = { 0: ['☀️', 'céu limpo'], 1: ['🌤️', 'poucas nuvens'], 2: ['⛅', 'parcialmente nublado'], 3: ['☁️', 'nublado'], 45: ['🌫️', 'neblina'], 48: ['🌫️', 'neblina'], 51: ['🌦️', 'garoa fraca'], 53: ['🌦️', 'garoa'], 55: ['🌧️', 'garoa forte'], 61: ['🌦️', 'chuva fraca'], 63: ['🌧️', 'chuva'], 65: ['🌧️', 'chuva forte'], 66: ['🌧️', 'chuva congelante'], 67: ['🌧️', 'chuva congelante'], 80: ['🌦️', 'pancadas de chuva'], 81: ['🌧️', 'pancadas de chuva'], 82: ['⛈️', 'pancadas fortes de chuva'], 95: ['⛈️', 'trovoadas'], 96: ['⛈️', 'trovoadas com granizo'], 99: ['⛈️', 'trovoadas com granizo'] };
const DS = ['segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado', 'domingo'];
let texto;
const d = f.daily || {};
if (!cid) {
  texto = 'Não achei a cidade *' + ped.local + '*. Me diga o nome da cidade (ex.: "Barueri" ou "Santana de Parnaíba").';
} else if (!Array.isArray(d.time) || !d.time.length) {
  texto = 'Não consegui a previsão de *' + cid.name + '* para ' + DateTime.fromISO(ped.dia).toFormat('dd/LL') + ' agora. A previsão vai só até 16 dias à frente; tente de novo em alguns minutos.';
} else {
  const dia = DateTime.fromISO(d.time[0], { zone: TZ });
  const hoje = DateTime.now().setZone(TZ).startOf('day');
  const rot = dia.hasSame(hoje, 'day') ? 'hoje' : dia.hasSame(hoje.plus({ days: 1 }), 'day') ? 'amanhã' : DS[dia.weekday - 1];
  const c = COD[d.weather_code[0]] || ['🌡️', 'tempo variável'];
  const prob = d.precipitation_probability_max ? d.precipitation_probability_max[0] : null;
  const mm = d.precipitation_sum ? d.precipitation_sum[0] : null;
  const onde = cid.name + (cid.admin1 ? ' (' + (cid.admin1 === 'São Paulo' ? 'SP' : cid.admin1) + ')' : '');
  const aviso = nrm(cid.name) !== nrm(ped.busca) ? NL + '_Busquei por "' + ped.local + '" e usei ' + onde + '._' : '';
  texto = c[0] + ' *Tempo em ' + onde + ' — ' + rot + ', ' + dia.toFormat('dd/LL') + '*' + NL +
    '🌡️ Mínima ' + Math.round(d.temperature_2m_min[0]) + '° · máxima ' + Math.round(d.temperature_2m_max[0]) + '°' + NL +
    '☔ Chuva: ' + (prob == null ? 'sem dado' : prob + '% de chance') + (mm ? ' (' + String(Math.round(mm * 10) / 10).replace('.', ',') + ' mm)' : '') + NL +
    c[0] + ' ' + c[1].charAt(0).toUpperCase() + c[1].slice(1) +
    (prob != null && prob >= 50 ? NL + NL + 'Vale levar guarda-chuva ☂️' : '') + aviso;
}
return { json: { numero: ped.numero, autor: ped.autor, teste: ped.teste, voz: 'dina', texto } };

const out = [];
const peds = $('Rotear').all(1);
$input.all().forEach((it, i) => {
  const ped = (peds[i] || peds[0] || { json: {} }).json;
  const r = it.json || {};
  const ms = Array.isArray(r.mensagens) ? r.mensagens : [];
  if (!ms.length && r.error) out.push({ json: { numero: ped.numero, autor: ped.autor, teste: ped.teste, voz: 'dina', texto: 'Não consegui fazer esse envio agora. Tente de novo em alguns minutos.' } });
  for (const m of ms) if (m && m.numero && m.texto) out.push({ json: { numero: String(m.numero), autor: String(m.autor_hist || ''), teste: ped.teste, voz: m.voz || 'dina', texto: String(m.texto) } });
});
return out;

// Ordena os resultados: nome igual ao pedido, estado pedido (ex.: ", SP"), São Paulo como padrão, população.
const ped = $('Rotear').item.json;
const nrm = x => String(x || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const UF = { ac: 'acre', al: 'alagoas', ap: 'amapa', am: 'amazonas', ba: 'bahia', ce: 'ceara', df: 'distrito federal', es: 'espirito santo', go: 'goias', ma: 'maranhao', mt: 'mato grosso', ms: 'mato grosso do sul', mg: 'minas gerais', pa: 'para', pb: 'paraiba', pr: 'parana', pe: 'pernambuco', pi: 'piaui', rj: 'rio de janeiro', rn: 'rio grande do norte', rs: 'rio grande do sul', ro: 'rondonia', rr: 'roraima', sc: 'santa catarina', sp: 'sao paulo', se: 'sergipe', to: 'tocantins' };
const partes = String(ped.local || '').split(/[,-]/).map(nrm).filter(Boolean);
const uf = partes.length > 1 ? (UF[partes[partes.length - 1]] || partes[partes.length - 1]) : '';
const rs = Array.isArray($json.results) ? $json.results.slice() : [];
const nota = r => (nrm(r.name) === nrm(ped.busca) ? 4 : 0) + (uf && nrm(r.admin1) === uf ? 3 : 0) + (nrm(r.admin1) === 'sao paulo' ? 2 : 0) + Math.min(1, (Number(r.population) || 0) / 1e7);
rs.sort((a, b) => nota(b) - nota(a));
return { json: { ...$json, results: rs } };
